import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="3mo",progress=False,auto_adjust=True); close=data["Close"]; volume=data["Volume"]; print("\n".join((lambda c,v:(lambda p,p5,mm20,rvol,r,s:f"{t}: {p:.2f} | Var 5j: {p5:+.2f}% | MM20: {mm20:.2f} | RVOL: {rvol:.2f} | RSI14: {r:.1f} | Score: {s}/100 | Signal: {'SURCHAUFFE' if p5>=8 or r>=75 else 'ACHAT' if s>=70 and 50<=r<70 else 'SURVEILLANCE' if s>=40 or 45<=r<75 else 'AUCUN SIGNAL'}")(float(c.iloc[-2]),(float(c.iloc[-2])/float(c.iloc[-7])-1)*100,float(c.iloc[-21:-1].mean()),float(v.iloc[-2])/float(v.iloc[-22:-2].mean()),100-(100/(1+(c.diff().iloc[-15:-1].clip(lower=0).mean()/(-c.diff().iloc[-15:-1].clip(upper=0).mean())))),(40 if float(c.iloc[-2])>float(c.iloc[-21:-1].mean()) else 0)+(30 if 3<(float(c.iloc[-2])/float(c.iloc[-7])-1)*100<8 else 0)+(30 if float(v.iloc[-2])/float(v.iloc[-22:-2].mean())>=1.5 else 0)))(close[t].dropna(),volume[t].reindex(close[t].dropna().index).dropna()) for t in tickers if t in close.columns and close[t].dropna().shape[0]>=22))
